import{r as i}from"./chunks/relatedArticles.DIHQAH-1.js";import{I as r,o as a,c as s,b6 as l,J as o,k as u}from"./chunks/framework.BUXTSoD9.js";const p=JSON.parse('{"title":"Von der Idee zum AI-Produkt - Easy-Vibe Lernpfad","description":"Vollst&auml;ndiger Lernpfad f&uuml;r AI-Programmierung: Von null bis Full-Stack-Entwicklung. Beherrschen Sie Vibe Coding, Claude Code, Cursor und andere AI IDE-Tools. Lernen Sie Produktdenken, Full-Stack-Entwicklung und AI-F&auml;higkeitsintegration.","frontmatter":{"title":"Von der Idee zum AI-Produkt - Easy-Vibe Lernpfad","description":"Vollst&auml;ndiger Lernpfad f&uuml;r AI-Programmierung: Von null bis Full-Stack-Entwicklung. Beherrschen Sie Vibe Coding, Claude Code, Cursor und andere AI IDE-Tools. Lernen Sie Produktdenken, Full-Stack-Entwicklung und AI-F&auml;higkeitsintegration."},"headers":[],"relativePath":"de-de/stage-1/learning-map/index.md","filePath":"de-de/stage-1/learning-map/index.md"}'),d={name:"de-de/stage-1/learning-map/index.md"},k=Object.assign(d,{setup(h){const n=i["de-de/stage-1/learning-map"]??[];return(g,e)=>{const t=r("RelatedArticlesSection");return a(),s("div",null,[e[0]||(e[0]=l('<h1 id="von-der-idee-zum-ai-produkt" tabindex="-1">Von der Idee zum AI-Produkt <a class="header-anchor" href="#von-der-idee-zum-ai-produkt" aria-label="Permalink to “Von der Idee zum AI-Produkt”">​</a></h1><div class="info custom-block"><p class="custom-block-title">Besonderer Dank</p><p>Besonderer Dank an die Studierenden der <strong>Tsinghua Universität Shenzhen International Graduate School</strong> für das Testen, Feedback und die Unterstützung dieses Kurses! Eure Meinungen und Beiträge haben diesen Kurs besser gemacht. <a href="https://github.com/datawhalechina/easy-vibe#-contributing--contributors" target="_blank" rel="noreferrer">Zur vollständigen Beiträgerliste</a></p></div><p>Früher war die Hürde für Softwareentwicklung sehr hoch: Man musste Programmierung und Algorithmen verstehen und über Jahre von Projekterfahrung verfügen. Heute ist das anders. Solange Sie eine Idee haben, kann AI Ihnen beim Schreiben von Code helfen.</p><p>Das ist eine gewaltige Veränderung: <strong>Programmiersprachen werden zu natürlichen Sprachen.</strong></p><p>Mit dem Aufkommen großer Sprachmodelle (LLMs) ist Entwicklung nicht mehr &quot;das exklusive Vorrecht von Tech-Genies&quot;, sondern ein Werkzeug, das jeder nutzen kann. Das einst schwierigste Problem war &quot;wie man Code schreibt&quot;; jetzt ist das schwierigste Problem: &quot;<strong>Was willst du erstellen?</strong>&quot;.</p><blockquote><p><strong>Was ist Vibe Coding?</strong> Kurz gesagt: &quot;Programmieren durch Sprechen&quot;. Vibe Coding bedeutet, dass Sie sich darauf verlassen können, ausschließlich mit AI zu kommunizieren, anstatt Code direkt zu schreiben, um Programmierprojekte abzuschließen.</p></blockquote><p>Natürlich ist es nur der erste Schritt, AI Code schreiben zu lassen. Um ein wirklich nutzbares Produkt zu erstellen, werden Sie auf folgende Probleme stoßen:</p><ul><li>Wie lässt man AI sauberen, wartbaren Code schreiben?</li><li>Wie fügt man zerstreuten Code zu einer lauffähigen Anwendung zusammen?</li><li>Wie bringt man die Anwendung wirklich online, damit sie von Menschen genutzt wird?</li><li>Wie integriert man AI-Fähigkeiten wie Textgenerierung und Bilderkennung in Ihr Produkt?</li></ul><p>In diesem Kurs finden Sie Antworten auf diese Fragen.</p><p>Egal ob Sie Studierende, Lehrkraft, Arzt, Arbeiter oder eine beliebige Person ohne technisches Vorwissen sind – ohne vorher jahrelang Programmieren gelernt zu haben, können Sie in zwei Wochen einen lauffähigen, demo-fähigen Produktprototyp erstellen.</p><table tabindex="0"><thead><tr><th>Ihre Identität</th><th>Was dieser Kurs Ihnen bietet</th></tr></thead><tbody><tr><td>Studierende</td><td>Hausaufgaben, Wettbewerbe, Gründung: Projekte selbständig umsetzen, ohne andere zu bitten</td></tr><tr><td>Berufstätige</td><td>Wiederkehrende Arbeit automatisieren, Effizienz steigern, sogar ein Nebenprojekt entwickeln</td></tr><tr><td>Produktmanager / Designer</td><td>Ideen bleiben nicht auf dem Papier; schnell ein Demo für Chef/Kunden erstellen</td></tr><tr><td>Gründer / Kleinunternehmer</td><td>Ideen kostengünstig validieren, ohne Tausende für eine Agentur auszugeben</td></tr><tr><td>Lehrkräfte / Pädagogen</td><td>Lehrmittel, Kursmaterialien, automatisierte Aufgaben erstellen, Lehr-Effizienz steigern</td></tr><tr><td>Ärzte / Anwälte / Fachkräfte</td><td>Professionelle Abläufe automatisieren, eigene Effizienz-Tools entwickeln</td></tr><tr><td>Jeder</td><td>AI nutzen, um konkrete Probleme im Leben/Beruf zu lösen, Unmögliches möglich machen</td></tr></tbody></table><p>In der AI-Ära sind Umsetzungskraft und Ideen stets wichtiger als Technik.</p><h2 id="wachstumspfad-von-ai-nutzen-k-ouml-nnen-zu-ai-produkte-erstellen-k-ouml-nnen" tabindex="-1">Wachstumspfad: Von &quot;AI nutzen können&quot; zu &quot;AI-Produkte erstellen können&quot; <a class="header-anchor" href="#wachstumspfad-von-ai-nutzen-k-ouml-nnen-zu-ai-produkte-erstellen-k-ouml-nnen" aria-label="Permalink to “Wachstumspfad: Von &quot;AI nutzen k&amp;ouml;nnen&quot; zu &quot;AI-Produkte erstellen k&amp;ouml;nnen&quot;”">​</a></h2><div class="stage-intro"><div class="stage-card"><div class="stage-icon">🎮</div><h3>Neueinsteiger</h3><p class="stage-role">AI-Programmierung erleben</p><div class="stage-tags"><span>Snake-Spiel</span><span>Null-Vorkenntnisse</span><span>Vibe Coding erleben</span><span>In Minuten generieren</span></div></div></div><div class="stage-grid"><div class="stage-card"><div class="stage-icon">🛠️</div><h3>Stage 1</h3><p class="stage-role">Produktmanager / Operations</p><div class="stage-tags"><span>AI IDE (Cursor/Claude)</span><span>Anforderungsanalyse &amp; Prototyp</span><span>AI-Fähigkeiten integrieren</span><span>Vollständige Demo-Entwicklung</span></div></div><div class="stage-card"><div class="stage-icon">💻</div><h3>Stage 2</h3><p class="stage-role">Junior-/Mid-Level Entwickler</p><div class="stage-tags"><span>Figma zu Code</span><span>Supabase Datenbank</span><span>Stripe-Zahlung</span><span>Dify Wissensbasis</span></div></div><div class="stage-card"><div class="stage-icon">🚀</div><h3>Stage 3</h3><p class="stage-role">Senior Entwickler / Architekt</p><div class="stage-tags"><span>Web/Mini-App/Multi-Plattform</span><span>MCP Advanced Tools</span><span>RAG &amp; LangGraph</span><span>Senior Engineer Mindset</span></div></div></div><p>Durch diesen vollständigen Lernpfad werden Sie erwerben:</p><ul><li><strong>Vibe Coding Entwicklungsfähigkeiten:</strong> Vibe Coding Denken und AI-Coding-Tools meisterhaft einsetzen, die Entwicklungseffizienz um ein Vielfaches steigern. Keine Syntax mehr auswendig lernen, sondern lernen, AI zur Generierung hochwertigen Codes zu leiten.</li><li><strong>Full-Stack-Entwicklungs-Know-how:</strong> Von UI-Design über Frontend-Implementierung, von Datenbank-Design bis API-Entwicklung, von lokaler Entwicklung bis Cloud-Deployment – den vollständigen Technologie-Stack moderner Web-Anwendungen beherrschen.</li><li><strong>AI-Fähigkeitsintegration:</strong> Lernen, verschiedene multimodale AI-APIs aufzurufen und AI-Fähigkeiten wie Text, Bild und Sprache nahtlos in Ihre Anwendungen zu integrieren. Durch RAG und andere Technologien intelligente Produkte aufbauen.</li><li><strong>Produktdenken und Operations-Fähigkeiten:</strong> Von Nutzerforschung über Anforderungszerlegung, von MVP-Design bis Produkt-Iteration, von Zahlungsintegration bis Nutzermanagement – einen vollständigen Produktentwicklungs- und Operations-Kreislauf bilden.</li></ul><h1 id="was-k-ouml-nnen-sie-nach-abschluss-tun" tabindex="-1">Was können Sie nach Abschluss tun? <a class="header-anchor" href="#was-k-ouml-nnen-sie-nach-abschluss-tun" aria-label="Permalink to “Was k&amp;ouml;nnen Sie nach Abschluss tun?”">​</a></h1><h2 id="stage-1-ihren-ersten-produktprototyp-erstellen" tabindex="-1">Stage 1: Ihren ersten Produktprototyp erstellen <a class="header-anchor" href="#stage-1-ihren-ersten-produktprototyp-erstellen" aria-label="Permalink to “Stage 1: Ihren ersten Produktprototyp erstellen”">​</a></h2><p>Diese Phase richtet sich an Personen, die überhaupt keine Programmiererfahrung haben oder nur ein bisschen können, sich aber nicht sicher fühlen. Sie müssen nicht erst eine Menge Theorie lernen, sondern steigen direkt ein und lernen beim Tun, AI-Tools zum Schreiben von Code zu nutzen.</p><p><strong>Nach Abschluss können Sie:</strong></p><ul><li>Mit AI-Programmier-Tools unabhängig eine Web-Anwendung erstellen</li><li>Produktideen in klickbare, interaktive Prototypen umsetzen</li><li>Dem Prototypen AI-Funktionen hinzufügen (z.B. Text-to-Image, intelligente Konversation)</li><li>Wissen, wie man Fehler diagnostiziert und behebt</li></ul><p>Kurz gesagt: Etwas erstellen, das &quot;läuft und anderen vorgeführt werden kann&quot;.</p><p>Wir können zunächst AI-Programmierung durch kleine Spiele erleben, dann lernen, AI-Programmier-Tools beim Schreiben von Code und Beheben von Fehlern zu unterstützen. Danach beginnen wir mit einfachen Seiten und erstellen schrittweise interaktive Multi-Page-Anwendungen, ergänzt um AI-Funktionen wie Text-to-Image und intelligente Konversation. Schließlich schließen Sie unabhängig ein vollständiges Projekt ab, sodass Ihre Ideen echte Umsetzungschancen erhalten.</p><h1 id="warum-projektbasiertes-training" tabindex="-1">Warum projektbasiertes Training? <a class="header-anchor" href="#warum-projektbasiertes-training" aria-label="Permalink to “Warum projektbasiertes Training?”">​</a></h1><blockquote><p><strong>Herausforderungen der echten Welt</strong></p><p>Der Grund ist eigentlich ganz einfach: Im aktuellen Zustand werden die meisten von Ihnen, direkt ins Berufsleben eintretend, bei echten Projekten und unter dem &quot;Druck&quot; von Chefs/Kunden kaum vorankommen. In der echten Welt sind häufigere Szenarien:</p></blockquote><blockquote><p>Ihr Betreuer / Ihr Chef: Wir möchten ein xxx machen, das Ziel ist es, den Effekt yyy zu erreichen.</p><p>Dokumentation? Fertige Frameworks? Detaillierte Anforderungsspezifikationen? Oft existieren diese nicht.</p></blockquote><p>Viele Aufgaben in der echten Arbeitswelt bestehen im Wesentlichen darin, in einer hochgradig unsicheren Umgebung nie gesehene Probleme zu lösen: Anforderungen sind vage, Grenzen verschieben sich, niemand sagt Ihnen die richtige Antwort. Sie müssen selbst recherchieren, experimentieren, Prototypen erstellen und ständig iterieren, um schließlich eine &quot;laufende, nutzbare, online-fähige&quot; Lösung zu präsentieren.</p><p>Dieser Kurs möchte genau das in einer relativ sicheren Umgebung tun: Ihnen eine &quot;simulierte Herausforderung&quot; im Voraus geben.</p><ul><li>Durch scheinbar anspruchsvolle Projektaufgaben zwingen wir Sie, Problemlösung, Designentwürfe und selbständige Informationssuche zu üben</li><li>Durch nicht &quot;idiotensichere&quot; Gerüste und Code lernen Sie, eine mittelgroße Codebasis zu lesen, zu verstehen und anzupassen</li><li>Durch den vollständigen Kreislauf von der Idee bis zum Launch erleben Sie den kompletten Prozess von 0 auf 1 eines echten Produkts</li></ul><p>Kurzfristig ist dieses Training anspruchsvoll; langfristig wird es Ihre Wettbewerbsfähigkeit bei der Jobsuche und Karriereentwicklung erheblich steigern: Sie können mehr verantworten, in unsicheren Umgebungen eher Durchbrüche finden und AI eher in echte Produkte umsetzen, statt bei &quot;Demo spielen&quot; stehen zu bleiben.</p><h1 id="die-kunst-des-fragens-eine-unerl-auml-ssliche-f-auml-higkeit-in-der-ai-auml-ra" tabindex="-1">Die Kunst des Fragens: Eine unerlässliche Fähigkeit in der AI-Ära <a class="header-anchor" href="#die-kunst-des-fragens-eine-unerl-auml-ssliche-f-auml-higkeit-in-der-ai-auml-ra" aria-label="Permalink to “Die Kunst des Fragens: Eine unerl&amp;auml;ssliche F&amp;auml;higkeit in der AI-&amp;Auml;ra”">​</a></h1><p>In der AI-Ära gehört auch das Fragen zu den &quot;Grundlagen&quot;. Bei gleichem Code und gleichem Fehler: <strong>Wie Sie fragen, bestimmt fast, welche Antwort AI geben kann</strong> – ob oberflächlich oder Schritt für Schritt mit umsetzbaren Lösungen.</p><p><strong>Gute Gewohnheit entwickeln:</strong> &quot;AI fragen&quot; als Teil des täglichen Entwicklungs-Workflows betrachten: Bei jeder Frage, bei der Sie nicht weiterkommen, sofort fragen.</p><h2 id="warum-ist-diese-f-auml-higkeit-unerl-auml-sslich" tabindex="-1">Warum ist diese Fähigkeit unerlässlich? <a class="header-anchor" href="#warum-ist-diese-f-auml-higkeit-unerl-auml-sslich" aria-label="Permalink to “Warum ist diese F&amp;auml;higkeit unerl&amp;auml;sslich?”">​</a></h2><ul><li><strong>Echte Dokumentation ist selten:</strong> Meistens stehen Sie vor unklaren Anforderungen, unfertigem Code und verstreuten Fehlermeldungen</li><li><strong>AI ist Ihr always-on Mentor + Kollege:</strong> Wer gut fragen kann, macht daraus &quot;hochwertige Pair-Programming&quot;-Sessions</li><li><strong>Das Leistungslimit wird durch Kommunikation bestimmt:</strong> Je mehr Schlüsselinformationen Sie liefern und je besser Sie das Ausgabeformat steuern, desto nutzbarer die Antworten</li></ul><p><strong>Häufiger Fehler:</strong> Nur &quot;Warum gibt es einen Fehler?&quot; zu fragen, bringt meist nur Spekulationen. Wenn Sie den Kontext vervollständigen, erhalten Sie umsetzbare Lösungen.</p><h2 id="wie-man-ai-informationen-zuf-uuml-hrt-screenshot-vs-copy-amp-paste" tabindex="-1">Wie man AI Informationen &quot;zuführt&quot;: Screenshot vs. Copy &amp; Paste <a class="header-anchor" href="#wie-man-ai-informationen-zuf-uuml-hrt-screenshot-vs-copy-amp-paste" aria-label="Permalink to “Wie man AI Informationen &quot;zuf&amp;uuml;hrt&quot;: Screenshot vs. Copy &amp;amp; Paste”">​</a></h2><p>Beide Methoden funktionieren, aber für unterschiedliche Zwecke:</p><table tabindex="0"><thead><tr><th>Methode</th><th>Geeignetes Szenario</th><th>Wichtige Anforderungen</th></tr></thead><tbody><tr><td><strong>Copy &amp; Paste</strong></td><td>Fehler-Stacktraces, Logs, Code, Konfiguration, API-Antworten</td><td>Möglichst vollständig, nicht nur eine Zeile mit Schlüsselwörtern</td></tr><tr><td><strong>Screenshot</strong></td><td>UI-Layout-Probleme, Interaktionsanomalien, Tool-Interface wo man Buttons nicht findet</td><td>Vollbild + wichtige Bereiche markieren, am besten mit einem Satz Textbeschreibung</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">Wichtige Voraussetzung</p><p><strong>Nicht alle AI-Modelle unterstützen Bildeingabe.</strong> Screenshot-Kommunikation erfordert multimodale AI-Fähigkeiten. Aktuell unterstützen Claude (Anthropic), GPT-4V/GPT-4o (OpenAI), Gemini (Google) sowie einige nationale große Modelle wie Qwen, Wenxin Yiyan etc. Bildeingabe.</p><p><strong>Wenn Ihre AI keine Bildeingabe unterstützt</strong>, können Screenshots nicht erkannt werden. Bitte verwenden Sie in diesem Fall Copy &amp; Paste zur Kommunikation.</p></div><h2 id="prompt-techniken-mit-denen-ai-gut-und-erkl-auml-rend-antwortet" tabindex="-1">Prompt-Techniken, mit denen AI &quot;gut und erklärend&quot; antwortet <a class="header-anchor" href="#prompt-techniken-mit-denen-ai-gut-und-erkl-auml-rend-antwortet" aria-label="Permalink to “Prompt-Techniken, mit denen AI &quot;gut und erkl&amp;auml;rend&quot; antwortet”">​</a></h2><p>Wenn Sie nicht nur die Antwort, sondern auch &quot;die Antwort verstehen&quot; wollen. Verwenden Sie ähnliche Anweisungen, die die Erklärungsqualität deutlich verbessern:</p><blockquote><p><strong>Lern-Frage-Beispiele</strong></p><ul><li>&quot;Bitte erkläre dieses Konzept zunächst in 5 Sätzen, und gib mir dann einige Fragen, um zu prüfen, ob ich es richtig verstanden habe.&quot;</li><li>&quot;Bitte erkläre diese Fehlermeldung im Detail; ich verstehe nicht, warum dieser Fehler auftritt.&quot;</li></ul></blockquote><h1 id="ich-habe-lange-durchgehalten-aber-es-klappt-nicht-ich-m-ouml-chte-aufgeben" tabindex="-1">Ich habe lange durchgehalten, aber es klappt nicht. Ich möchte aufgeben <a class="header-anchor" href="#ich-habe-lange-durchgehalten-aber-es-klappt-nicht-ich-m-ouml-chte-aufgeben" aria-label="Permalink to “Ich habe lange durchgehalten, aber es klappt nicht. Ich m&amp;ouml;chte aufgeben”">​</a></h1><p>Vielleicht ist Ihre Methode falsch. Kämpfen Sie nicht allein im Dunkeln. Sprechen Sie mit den Autoren und Tutoren: Teilen Sie ehrlich, was Sie bereits versucht haben, wo genau Sie feststecken und wie Ihr aktueller Gemütszustand ist. Oft reicht eine kleine Richtungsänderung oder das Auffüllen eines fehlenden Schlüsselwissens, um weiterzumachen.</p><h1 id="ich-finde-einige-tutorial-designs-unangemessen" tabindex="-1">Ich finde einige Tutorial-Designs unangemessen <a class="header-anchor" href="#ich-finde-einige-tutorial-designs-unangemessen" aria-label="Permalink to “Ich finde einige Tutorial-Designs unangemessen”">​</a></h1><p>Feedback ist jederzeit willkommen – kontaktieren Sie die Autoren, reichen Sie ein Issue ein oder geben Sie direkt in der Gruppe/im Unterricht Feedback. Wir hoffen sehr, dieses Tutorial gemeinsam mit Ihnen immer besser zu machen: Was unklar ist, was schlecht erlebbar ist, wo Sie Zeit verschwendet haben – alles kann offen kritisiert werden. Je authentischer und konkreter das Feedback, desto mehr hilft es späteren Lernenden, Fehler zu vermeiden.</p><h1 id="referenzen" tabindex="-1">Referenzen <a class="header-anchor" href="#referenzen" aria-label="Permalink to “Referenzen”">​</a></h1><ul><li><a href="https://nju-projectn.github.io/ics-pa-gitbook/ics2025/" target="_blank" rel="noreferrer">Nanjing Universität, Informatik-Fakultät, Computer System Grundlagen Kurspraktikum</a></li></ul>',50)),o(t,{title:"Was Sie als Nächstes lernen können",description:"Folgen Sie dem Pfad 'von AI nutzen zu Produkterstellung' und gehen Sie weiter.",items:u(n)},null,8,["items"])])}}});export{p as __pageData,k as default};
